-- La lettera finale del Cruciverba diventa modificabile dall'editor admin condiviso.
INSERT INTO content_entries (content_key, label, content_type, versioning_mode, body, created_by, created_at, updated_at)
SELECT 'cruciverba.lettera-finale', 'Cruciverba — lettera finale', 'paragraphs', 'replace',
       'Hey! Complimenti per aver completato il cruciverba! Spero non sia stato troppo difficile ahaha. Dovresti ricordarti le nostre cose 😒. Mi è venuta questa idea il giorno che ero a quella festa di laurea, quella in cui c''era Desy, Perfect e chi più ne ha più ne metta ahaha. Da quel giorno un''idea ha tirato l''altra, ed è nata anche l''idea di portare il nostro mondo allo step successivo, quello che probabilmente meritava da subito ahaha. Lo so, forse un po'' deludente il fatto che la tua ricompensa per averlo finito sia l''ennesima letterina ahaha, ma vedi il lato positivo, forse la vera ricompensa non è questa lettera, ma tutti i ricordi che abbiamo ricordato insieme, io mentre creavo questo cruciverba e tu mentre lo facevi. Spero che sia stato bello anche per te e che sia stato un piccolo viaggio nel passato e che hai rivisto cose che forse ti eri anche dimenticata. Beh che dire adesso? È difficile scrivere una lettera in modo che sia "senza tempo" sai ahaha? Magari non hai completato questo cruciverba subito e magari adesso qualcosa è diverso, chi lo sa ahaha. Sicuramente posso dirti che per me sei una persona davvero speciale e che ti voglio un bene dell''anima. Spero che passeremo ancora tanti di quei giorni, spero che creeremo tanti altri ricordi stupendi, come quelli che abbiamo già, ma perché no? Anche di più belli. E spero che un giorno saranno così tanti che ci sarà bisogno di un secondo cruciverba ahaha. Beh comunque come sempre vorrei dirti davvero tante cose, ma questo è solo un cruciverba e non c''è bisogno che te le dica qui. Spero che tu ti sia divertita a completarlo, perché io mi sono divertito a crearlo ahaha. Quindi insomma, ancora complimenti e buona continuazione nel mondo bianco! Ti voglio benissimo piccolina mia ❤️‍🔥',
       u.id, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
FROM users u
WHERE u.email = 'rory982011@gmail.com';
